Atlas.PLATES = [
 {"id": "2-1", "t": "Bone Structure and Classification", "d": "Introduces bone as a mineralized connective tissue and contrasts dense compact bone with trabecular spongy bone. Labels the regions of a long bone (epiphysis, metaphysis, diaphysis, marrow cavity, periosteum, articular cartilage) and the microscopic osteon with its central canal, lamellae and osteocytes. Also names the three bone-cell types that build, maintain and resorb bone during constant remodeling.", "clin": [{"t": "Rickets", "d": "If calcium is lacking during growth, the new bone matrix doesn't mineralize properly. The cause is too little dietary calcium, too little vitamin D (needed to absorb calcium from the gut), or both."}]},
 {"id": "2-2", "t": "External Features of the Skull", "d": "Divides the skull into the brain case (calvaria/neurocranium) and the facial skeleton, counting 22 bones: 8 cranial and 14 facial, with the ear ossicles excluded. Each cranial and facial bone is colored in anterior, lateral, superior and inferior views. The cranial bones are joined by immobile fibrous sutures, and the plate names eight of them, from the coronal to the occipitomastoid.", "clin": [{"t": "Pterion and epidural hematoma", "d": "The skull is thin where the frontal, parietal, sphenoid and temporal bones meet. A blow there can tear the middle meningeal artery under the bone and cause bleeding outside the dura."}]},
 {"id": "2-3", "t": "Internal Features of the Skull", "d": "Shows the skull in sagittal section and the seven bones that build the lateral wall of the nasal cavity, plus the parts of the nasal septum. Divides the cranial floor into anterior, middle and posterior fossae by the brain regions they hold. Maps each foramen of the cranial base to the cranial nerves or vessels passing through it. Corrected: the book labels the abducent nerve (IV); it is cranial nerve VI (IV is the trochlear)."},
 {"id": "2-4", "t": "Mandible and Temporomandibular Joint", "d": "Covers the parts of the mandible, the 16 lower teeth by type, and the mandibular foramen for the inferior alveolar nerve and vessels. Describes the TMJ as a modified hinge joint split by a fibrocartilage disc into two synovial compartments, which allows both hinging and forward gliding when the mouth opens wide. Notes how often the jaw is fractured and how it can dislocate.", "clin": [{"t": "Mandible fracture", "d": "The exposed jaw is the second most often broken facial bone, after the nasal bone."}, {"t": "TMJ dislocation", "d": "The mandibular condyle can slip forward past the articular eminence, sometimes from just a big yawn. It is painful."}]},
 {"id": "2-5", "t": "Vertebral Column", "d": "Counts the 33 vertebrae by region and explains the primary (thoracic, sacral) versus secondary (cervical, lumbar) curvatures. Lists the parts of a typical vertebra and the structure of the intervertebral disc (nucleus pulposus inside anulus fibrosus). Introduces the longitudinal, flaval, interspinous and supraspinous ligaments, and the exaggerated curves (scoliosis, kyphosis, lordosis).", "clin": [{"t": "Disc herniation ('slipped disc')", "d": "Pressure or age-related drying weakens the anulus fibrosus, so the nucleus pulposus can push through and press on an exiting nerve root."}, {"t": "Abnormal spinal curves", "d": "Scoliosis is a lateral, rotated curve of the thoracic or lumbar spine, more common in adolescent girls. Hunchback (excess thoracic kyphosis) usually comes from poor posture or osteoporosis. Swayback (excess lumbar lordosis) comes from weak trunk muscles or obesity and is common late in pregnancy."}]},
 {"id": "2-6", "t": "Cervical and Thoracic Vertebrae", "d": "Contrasts the atlas (ring with no body or spine), the axis (with its dens) and the typical C3–C7 vertebrae, which have transverse foramina for the vertebral artery and short bifid spines. Describes thoracic vertebrae: a heart-shaped body, costal facets for the ribs, and long downward-sloping spines. Notes that the neck is the most mobile region and the thoracic spine is stiffer because of its rib attachments.", "clin": [{"t": "Cervical nerve root compression", "d": "The cervical intervertebral foramina are narrow, so the nerve roots passing through them are at risk of being compressed."}]},
 {"id": "2-7", "t": "Lumbar, Sacral, and Coccygeal Vertebrae", "d": "Compares thoracic, lumbar, sacral and coccygeal vertebrae in a table. Lumbar bodies are massive and kidney-shaped, with short spines, and L5 is the largest vertebra. Describes the sacrum (five fused segments with paired foramina, a median crest and a sacral hiatus) and the coccyx. Illustrates how a posterolateral disc herniation compresses an exiting spinal nerve.", "clin": [{"t": "Posterolateral disc herniation", "d": "With stress or age the discs dry out. The nucleus usually escapes posterolaterally, where it can compress the spinal nerve or its root at the intervertebral foramen."}]},
 {"id": "2-8", "t": "Thoracic Cage", "d": "Covers the sternum (manubrium, body, xiphoid), the 12 pairs of ribs and their parts, and the true, false and floating rib groups. Its table classifies the sternoclavicular, sternocostal, costochondral and interchondral joints, and it introduces the clavicle and scapula as the pectoral girdle. Ends with the functions of the cage and the patterns of chest trauma. The table text interleaves columns in places but is readable.", "clin": [{"t": "Rib fractures and chest trauma", "d": "Chest trauma includes rib fractures (ribs 1, 11 and 12 are usually spared), crush injuries and penetrating wounds. Broken ribs hurt a lot because the cage moves with every breath."}]},
 {"id": "2-9", "t": "Joints and Ligaments of the Spine", "d": "Distinguishes the craniovertebral joints (atlanto-occipital for nodding, atlanto-axial for rotation) and their ligaments, such as the alar, cruciate and tectorial membrane. Explains that vertebral arches meet at plane synovial facet joints and vertebral bodies at cartilaginous symphyses with discs. Tabulates what each spinal ligament attaches to and limits. Closes with whiplash as a hyperextension–flexion injury.", "clin": [{"t": "Whiplash", "d": "A lay term for a hyperextension injury of the neck, usually from a rear-end collision. The neck snaps back, then rebounds into hard flexion. Well-adjusted headrests greatly reduce it."}]},
 {"id": "2-10", "t": "Pectoral Girdle and Arm", "d": "Presents the clavicle, scapula and humerus. The clavicle is the girdle's only direct link to the trunk. Labels the scapular borders, angles, fossae, spine, acromion and coracoid, and the humeral tubercles, epicondyles, capitulum and trochlea. Covers clavicle fractures and surgical-neck fractures of the humerus. 17 muscles attach to the scapula; the text says 16, but the plate's own table counts 17.", "clin": [{"t": "Clavicle fracture", "d": "The most often broken bone in the body, especially in children. It usually comes from a fall on an outstretched hand or a direct hit to the shoulder, and it usually breaks in the middle third."}, {"t": "Humeral surgical neck fracture", "d": "A common fracture site that puts the axillary nerve at risk."}, {"t": "Scapular fracture", "d": "Relatively uncommon."}]},
 {"id": "2-11", "t": "Shoulder Joint", "d": "Describes the glenohumeral joint as a shallow, loose ball-and-socket joint deepened by the glenoid labrum and stabilized by the four rotator cuff tendons. Covers the acromioclavicular joint, the coracoclavicular ligaments, the shoulder ligaments, and the subacromial, subdeltoid and subscapular bursae. Clinical notes cover supraspinatus impingement with tendinitis and bursitis, and the predominance of anterior dislocations.", "clin": [{"t": "Supraspinatus impingement, tendinitis and bursitis", "d": "Repeated joint movement can inflame the surrounding tendons and then the bursae. The supraspinatus tendon is especially vulnerable to pinching between the greater tubercle, the acromion and the coraco-acromial ligament."}, {"t": "Anterior shoulder dislocation", "d": "About 95% of shoulder dislocations are anterior, often from a throwing motion that strains the capsule and the front of the rotator cuff (especially subscapularis). The shallow socket and loose capsule make the shoulder one of the most often dislocated joints."}]},
 {"id": "2-12", "t": "Forearm and Elbow Joint", "d": "Names the radius (lateral, shorter) and ulna (medial), the interosseous membrane, and how the radius crosses the ulna in pronation. Breaks the elbow into humero-ulnar and humeroradial hinge components and the proximal radio-ulnar pivot, with their collateral and anular ligaments. Notes the cubital fossa as a venipuncture site and posterior elbow dislocation after a fall on the hand.", "clin": [{"t": "Cubital fossa venipuncture", "d": "The area in front of the elbow is a common place to draw blood or give fluids through a vein."}, {"t": "Elbow dislocation", "d": "The third most common dislocation, after the shoulder and the fingers. It usually follows a fall on an outstretched hand and is most often posterior."}]},
 {"id": "2-13", "t": "Wrist and Hand", "d": "Counts the 29 bones of the wrist and hand: 8 carpals in two rows, 5 metacarpals, 14 phalanges and 2 sesamoids. Also describes the carpal arch that the flexor retinaculum turns into the carpal tunnel. The table gives the shape behind each carpal's name and the common fracture sites. Corrected: the table puts 'most commonly fractured carpal' on the lunate row; the scaphoid is the most commonly fractured carpal.", "clin": [{"t": "Scaphoid fracture", "d": "The scaphoid is the most commonly fractured carpal; it sits in the floor of the anatomical snuffbox. (The book's table misplaces this note on the lunate row.)"}, {"t": "Fifth metacarpal fracture", "d": "The fifth metacarpal is the most often broken metacarpal."}, {"t": "Distal phalanx of middle finger", "d": "A commonly fractured phalanx."}]},
 {"id": "2-14", "t": "Wrist and Finger Joints and Movements", "d": "Tabulates the wrist and hand joints from radiocarpal (ellipsoid) through intercarpal, midcarpal and carpometacarpal (plane), the thumb saddle joint, MCP (condyloid) and IP (hinge) joints, with their ligaments. Illustrates thumb movements, including opposition and reposition. Corrected: the table's 'Distal Radiocarpal (pivot) Joint' row is the distal radio-ulnar joint, and its radial collateral ligament runs to the scaphoid, not the triquetrum.", "clin": [{"t": "Thumb CMC arthritis", "d": "The trapezium–first metacarpal saddle joint is a common site of arthritis."}, {"t": "Splinting a broken finger", "d": "The MCP collateral ligaments are slack in extension, so a fractured digit is casted in flexion. Otherwise the ligament shortens while it heals."}]},
 {"id": "2-15", "t": "Pelvic Girdle", "d": "Shows the hip bone as the fusion of ilium, ischium and pubis meeting at the acetabulum, which joins the sacrum posteriorly and the opposite hip bone at the pubic symphysis. Labels the iliac spines, sciatic notches, ischial spine and tuberosity, and the sacro-iliac, sacrotuberous, sacrospinous and iliolumbar ligaments. Notes male–female pelvic differences. Corrected: the table puts the sacrococcygeal disc between S5 and 'C1'; it is S5 and Co1, the first coccygeal segment.", "clin": [{"t": "Iliolumbar avulsion", "d": "The iliolumbar ligament can be involved in an avulsion fracture."}, {"t": "Weak spot of ilium", "d": "The table describes the ala (wing) of the ilium as a weak spot."}]},
 {"id": "2-16", "t": "Hip Joint", "d": "Describes the hip as a ball-and-socket joint built for stability rather than range, with an acetabular labrum deepening the socket. Covers the three capsular ligaments (iliofemoral 'Y', pubofemoral, ischiofemoral), what each limits, the transverse acetabular ligament, and the ligament of the femoral head carrying an artery. Notes femoral neck fractures, from trauma in the young and from osteoporosis and falls in the elderly.", "clin": [{"t": "Hip (femoral neck) fracture", "d": "Hip fractures are common. In young people they usually follow trauma; in older people they are linked to osteoporosis and a fall. The femoral neck is the usual site."}]},
 {"id": "2-17", "t": "Thigh and Leg Bones", "d": "Covers the femur (head, neck, trochanters, condyles, epicondyles), the patella as the largest sesamoid in the quadriceps tendon, the weight-bearing tibia and the non-weight-bearing fibula. Notes that the tibial shaft can be felt under the skin from knee to ankle. Gives typical fracture sites for each bone, and warns that a fibular neck fracture threatens the common fibular nerve.", "clin": [{"t": "Femoral neck fracture", "d": "Most femoral fractures cross the neck, inside the joint capsule."}, {"t": "Tibial shaft fracture", "d": "Most often at the narrowest part of the shaft, about one third of the way down."}, {"t": "Distal fibula fracture", "d": "Most common just above the lateral malleolus, on the outside of the ankle."}, {"t": "Fibular neck fracture", "d": "A break at the fibular neck can injure the common fibular nerve."}]},
 {"id": "2-18", "t": "Knee Joint", "d": "Describes the knee as a condylar synovial joint whose femur rotates medially at full extension to lock it. Tabulates the extracapsular ligaments (collaterals, patellar, popliteal) and intracapsular ones (menisci, cruciates, transverse, meniscofemoral), plus the patellofemoral joint and the knee bursae. Explains ACL rupture, the anterior drawer test and the 'unhappy triad'.", "clin": [{"t": "ACL rupture and the unhappy triad", "d": "The ACL often tears in sports when the knee twists over a planted foot. The anterior drawer sign tests it: the tibia slides forward on the femur. Because the medial meniscus is attached to the tibial collateral ligament, ACL tears often come with tears of both. All three together are the 'unhappy triad'."}, {"t": "Medial meniscus tear", "d": "The C-shaped medial meniscus tears often."}]},
 {"id": "2-19", "t": "Bones of the Ankle and Foot", "d": "Counts the 28 bones of the foot: 7 tarsals, 5 metatarsals, 14 phalanges and 2 sesamoids. Describes each tarsal's key features, such as the talar trochlea, sustentaculum tali, navicular tuberosity and cuboid groove. Explains the medial longitudinal and transverse arches.", "clin": [{"t": "Prominent navicular tuberosity", "d": "A large navicular tuberosity can cause pain on the inner foot in tight shoes."}, {"t": "Stubbed fifth toe", "d": "A common injury."}]},
 {"id": "2-20", "t": "Ankle and Foot Joints", "d": "Tabulates the ankle and foot joints: the tibiofibular syndesmosis, the talocrural hinge, the subtalar, talocalcaneonavicular and calcaneocuboid joints for inversion and eversion, and the tarsometatarsal, intermetatarsal, MTP and IP joints. Highlights the three-part lateral ligament, the deltoid ligament and the spring ligament. Clinical notes cover calcaneal fractures from heel landings and inversion ankle sprains.", "clin": [{"t": "Calcaneal fracture", "d": "The most common tarsal fracture, usually from landing hard on the heel after a fall from height. The talus is driven into the spongy calcaneus, which gives way."}, {"t": "Inversion ankle sprain", "d": "Most ankle sprains happen when the foot rolls onto its outer edge with the sole turned inward. This stretches or tears the parts of the lateral collateral ligament (anterior talofibular, calcaneofibular, posterior talofibular). The lateral ligament is described as weak and often sprained."}]},
 {"id": "3-1", "t": "Muscles of Facial Expression", "d": "The facial muscles all develop from the second pharyngeal arch and are supplied by branches of the facial nerve (CN VII). Most run from facial bone or fascia into the skin, so they move the skin of the scalp, face and front of the neck rather than a joint. The plate tabulates eight of the main ones and flags Bell's palsy as the classic nerve lesion.", "clin": [{"t": "Bell's palsy", "d": "Inflammation of the facial nerve on one side leaves that side's facial muscles slack, so the face looks uneven; the person may be unable to frown, wrinkle the forehead, shut the eye tightly, smile, purse the lips or tense the neck skin."}]},
 {"id": "3-2", "t": "Muscles of Mastication", "d": "Four paired chewing muscles act on the mandible, arise from the first pharyngeal arch, and share one nerve, the mandibular division of the trigeminal (CN V3). Temporalis, masseter and medial pterygoid close the jaw, while the lateral pterygoids drive protrusion and side-to-side grinding. Tetanus ('lockjaw') is the clinical tie-in.", "clin": [{"t": "Tetanus (lockjaw)", "d": "The Clostridium tetani toxin acts on the nervous system and causes painful sustained muscle contraction, notably of the masseter; vaccination prevents it, so keeping immunizations current matters."}]},
 {"id": "3-3", "t": "Extra-ocular Muscles", "d": "Six skeletal muscles turn the eyeball and a seventh, levator palpebrae superioris, lifts the upper lid; three cranial nerves (III, IV, VI) supply them. Their anatomical actions are compound, so clinicians isolate each one by having the client track a finger through an H-shaped pattern. Intrinsic smooth muscles of the eye are deferred to Chapter 4.", "clin": [{"t": "Testing the extra-ocular muscles", "d": "Because these muscles work in combinations, examiners have the eyes follow a finger through an H pattern to isolate each muscle; any weakness found must then be traced to the muscle itself or its nerve."}]},
 {"id": "3-4", "t": "Muscles of the Tongue and Palate", "d": "Intrinsic tongue muscles change the tongue's shape, while four extrinsic '-glossus' muscles move it; all are hypoglossal (CN XII) except palatoglossus (vagus). Four muscles act on the soft palate during swallowing, and the plate closes with the four kinds of lingual papillae. The genioglossus is singled out as remarkably strong for its size."},
 {"id": "3-5", "t": "Muscles of the Pharynx and Swallowing", "d": "Three stacked constrictors and two longitudinal muscles (stylopharyngeus, salpingopharyngeus) form the muscular throat tube, which joins the esophagus near C6-C7. The constrictors fire top-down to push a food bolus along, and the plate walks through the sequence of swallowing (deglutition). It also names the nasal, oral and laryngeal parts of the pharynx."},
 {"id": "3-6", "t": "Intrinsic Muscles of the Larynx and Phonation", "d": "The larynx sits at about C3-C6 and is built from nine cartilages; its small intrinsic muscles, all vagus-supplied, tension the vocal ligaments and open or close the spaces between the folds. The posterior crico-arytenoids are the only abductors of the vocal folds, which keeps the airway open. Hoarseness is the clinical note.", "clin": [{"t": "Hoarseness", "d": "Anything that stops the vocal folds vibrating or meeting properly causes hoarseness; swelling from smoking, voice overuse, reflux, coughing or infection is most common, with scarring, nodules, cysts and cancer as other causes."}]},
 {"id": "3-7", "t": "Muscles of the Neck", "d": "Neck muscles carve the neck into a posterior triangle and an anterior triangle with four subdivisions that surgeons use as landmarks. The table covers the sternocleidomastoid plus the suprahyoid and infrahyoid ('strap') muscles that position the hyoid and larynx in swallowing. Three deep cervical fascial layers wrap the neck into tight compartments, which matters for infections and masses.", "clin": [{"t": "Fascial compartments of the neck", "d": "Three deep cervical fascial layers (investing, pretracheal, prevertebral) bind neck structures into tight spaces; infections or tumors there can compress soft structures and cause marked pain, though the layers can also limit spread. The carotid sheath, holding the carotid artery, internal jugular vein and vagus, blends with them."}]},
 {"id": "3-8", "t": "Prevertebral Muscles", "d": "Muscles lying in front of the cervical spine flex and support the head and neck. The scalenes run down to the first two ribs, act as accessory breathing muscles, and frame the path of the subclavian artery and vein. The clinical note describes the retropharyngeal 'danger' space.", "clin": [{"t": "Retropharyngeal 'danger' space", "d": "The gap between the pretracheal and prevertebral fascia lets infection travel from the skull base down into the superior mediastinum, which is why clinicians call it the danger space."}]},
 {"id": "3-9", "t": "Superficial and Intermediate Back Muscles", "d": "The superficial back layer (trapezius, latissimus dorsi, levator scapulae, rhomboids) migrated onto the back during development and actually moves the upper limb through the scapula and humerus. The intermediate layer (serratus posterior superior and inferior) attaches to ribs and helps with breathing. Apart from the trapezius, these are supplied by ventral rami."},
 {"id": "3-10", "t": "Deep (Intrinsic) Back Muscles", "d": "The true back muscles lie in three layers: the splenius group, the erector spinae (iliocostalis, longissimus, spinalis), and the deep transversospinal group, plus the suboccipital muscles under the skull. They extend, side-bend and rotate the spine and head and give postural support. Uniquely, they are supplied by dorsal rami of the spinal nerves."},
 {"id": "3-11", "t": "Thoracic Wall Muscles", "d": "Three layers of intercostal muscles fill the rib spaces and keep them stiff so they neither bulge nor collapse during breathing. Their individual effects on rib movement are hard to pin down even with EMG. The intercostal nerve and vessels run between the internal and innermost layers, under each rib.", "clin": [{"t": "Chest tube / needle placement", "d": "When fluid, pus, blood or air must be drained from the pleural cavity, the needle or catheter is placed carefully to miss the intercostal nerve and vessels, which run in the groove along the lower edge of each rib."}]},
 {"id": "3-12", "t": "Anterior Abdominal Wall Muscles", "d": "The external oblique, internal oblique and transversus abdominis continue the three thoracic wall layers around the abdomen, and their aponeuroses build the rectus sheath around the rectus abdominis. Together they raise abdominal pressure, assist forced expiration, and flex and rotate the trunk. The plate explains how the sheath changes below the arcuate line and lists common hernia types.", "clin": [{"t": "Abdominal wall hernias", "d": "Weak spots in the abdominal wall allow outpouchings: umbilical (young children or over 40), along the linea alba in the epigastrium, at old surgical scars (incisional), and in the groin (inguinal)."}]},
 {"id": "3-13", "t": "Muscles of the Male Inguinal Region", "d": "As the testis descends through the inguinal canal it collects three coverings from the abdominal wall layers, including the cremasteric fascia that carries cremaster muscle fibers. The plate lists the contents of the spermatic cord and the features of the canal. It explains why inguinal hernias are much more common in males and distinguishes indirect from direct hernias.", "clin": [{"t": "Indirect vs direct inguinal hernias", "d": "Indirect hernias (about three-quarters) start lateral to the inferior epigastric vessels and follow the deep ring and canal inside the spermatic cord; direct hernias (about a quarter) push through the canal's back wall medial to those vessels and stay outside the cord. Males are far more often affected because of testicular descent."}]},
 {"id": "3-14", "t": "Muscles of the Posterior Abdominal Wall", "d": "Psoas major, iliacus, quadratus lumborum and the diaphragm line the back of the abdominal cavity. Psoas and iliacus fuse functionally as the iliopsoas, the main hip flexor, while the diaphragm drives quiet inspiration by pulling its central tendon down. A psoas abscess can track down the muscle's fascial sheath.", "clin": [{"t": "Psoas abscess", "d": "An infected intervertebral disc next to the psoas can produce an abscess that starts at the muscle's upper attachment and tracks down inside its fascial sheath, sometimes below the inguinal ligament."}]},
 {"id": "3-15", "t": "Muscles of the Pelvis", "d": "Obturator internus and piriformis line the side walls of the pelvis and pass to the femur, while levator ani and coccygeus form the pelvic diaphragm. The book frames the pelvic floor muscles as former tail muscles repurposed to carry the viscera in an upright biped. Levator ani is three fused muscles (pubococcygeus, puborectalis, iliococcygeus).", "clin": [{"t": "Levator ani and defecation", "d": "The rectum-anal canal junction normally sits at about a right angle, helping keep it closed; during defecation the levator ani (especially fibers around the rectum) and the anal sphincters relax, widening the angle by roughly 40-50 degrees so the canal opens."}]},
 {"id": "3-16", "t": "Muscles of the Perineum", "d": "The diamond-shaped perineum splits into a front urogenital triangle and a rear anal triangle. Its small skeletal muscles surround erectile tissue, anchor to the central tendon of the perineum, or act as voluntary sphincters, and all are supplied by the pudendal nerve (S2-S4). Episiotomy is the clinical note.", "clin": [{"t": "Episiotomy", "d": "In childbirth an incision may be made midline or posterolaterally to enlarge the opening and avoid extensive tearing; careful repair is needed to preserve the central tendon of the perineum, a key support for the perineal muscles."}]},
 {"id": "3-17", "t": "Posterior Shoulder Muscles", "d": "Muscles attached to the scapula move it and the shoulder joint; past roughly 20 degrees of abduction the scapula starts rotating so the glenoid turns upward. Four of them (supraspinatus, infraspinatus, teres minor, subscapularis) form the rotator cuff, which steadies the shallow glenohumeral joint. Supraspinatus tendon wear and anterior-inferior dislocation are the clinical points.", "clin": [{"t": "Rotator cuff injury and shoulder dislocation", "d": "The cuff reinforces the shoulder above, behind and in front, so nearly all (about 95%) dislocations go anterior-inferiorly. Repeated throwing-type motion stresses the cuff, especially the supraspinatus tendon rubbing under the acromion and coraco-acromial ligament, and tears are common in athletes."}]},
 {"id": "3-18", "t": "Anterior Shoulder Muscles", "d": "Deltoid, pectoralis major and minor, serratus anterior and subclavius attach to the pectoral girdle or humerus and move the girdle and shoulder. Together with the posterior shoulder muscles they form the walls of the axilla, whose six boundaries the plate lists. The deltoid's three parts have different actions."},
 {"id": "3-19", "t": "Arm Muscles", "d": "An intermuscular septum divides the arm into an anterior flexor compartment (biceps, brachialis, coracobrachialis) and a posterior extensor compartment (triceps, with anconeus nearby). Brachialis, not biceps, is the strongest elbow flexor, and biceps is a strong supinator when the elbow is bent. Biceps tendon rupture is the clinical note.", "clin": [{"t": "Biceps tendon rupture", "d": "The biceps tendon ruptures spontaneously more often than any other tendon, usually the long-head tendon and usually after 40, often alongside rotator cuff injury or repeated heavy lifting; belly ruptures are rare."}]},
 {"id": "3-20", "t": "Pronation and Supination of the Radio-ulnar Joints", "d": "Two muscles pronate (pronator teres near the elbow, pronator quadratus near the wrist) by swinging the radius across a stationary ulna, and two supinate (supinator and biceps brachii). The biceps supinates strongly when the elbow is bent; with the elbow straight the supinator does the work. The clinical note shows how these muscles pull radial fracture fragments out of line.", "clin": [{"t": "Radius fractures and muscle pull", "d": "If the radius breaks above the pronator teres insertion, biceps and supinator pull the upper piece into flexion and supination while the pronators pronate the lower piece. If it breaks below that insertion, the upper piece stays neutral and pronator quadratus, unopposed, pronates the lower piece."}]},
 {"id": "3-21", "t": "Anterior Forearm Muscles", "d": "The anterior forearm compartment flexes the wrist and fingers, with a superficial layer from the medial epicondyle and a deep layer from the radius, ulna and interosseous membrane. Most are median-nerve muscles; flexor carpi ulnaris and the medial half of flexor digitorum profundus are ulnar. Palmaris longus is missing in about 10% of people."},
 {"id": "3-22", "t": "Posterior Forearm Muscles", "d": "The posterior compartment extends the wrist and fingers; its superficial layer comes mostly from the lateral epicondyle and its deep layer from the forearm bones. All are supplied by the radial nerve, including brachioradialis, which actually flexes the elbow. Wrist extension strengthens grip, and tennis elbow (a tendinosis of extensor carpi radialis brevis) is the clinical note.", "clin": [{"t": "Tennis elbow (lateral epicondylitis)", "d": "Despite the name, it is mainly a tendinosis of extensor carpi radialis brevis near the lateral epicondyle, and most people with it do not play tennis; pain sits just below and behind the epicondyle and worsens with resisted wrist extension, and may also involve the nerve or the joint."}]},
 {"id": "3-23", "t": "Intrinsic Hand Muscles", "d": "Thenar and hypothenar groups form the two fleshy mounds of the palm, with adductor pollicis, lumbricals and interossei lying deeper. Palmar interossei adduct the fingers and dorsal interossei abduct them (the PAD/DAB memory aid). The median nerve supplies the thenar group and lateral two lumbricals; the ulnar nerve supplies the rest."},
 {"id": "3-24", "t": "Summary of Upper Limb Muscles", "d": "A review plate that groups upper limb muscles by the joint they move and the action they perform, from scapula to finger joints. The guiding rule is to learn each compartment's main job, since muscles rarely act alone. Back and chest muscles mostly move the shoulder, arm muscles the elbow, and forearm muscles the wrist and fingers."},
 {"id": "3-25", "t": "Gluteal Muscles", "d": "The buttock muscles extend, abduct and laterally rotate the femur; gluteus maximus is the body's strongest muscle overall and powers rising from a chair and climbing stairs. Gluteus medius and minimus abduct and level the pelvis during walking, and a group of small deep rotators (piriformis, obturator internus, gemelli, quadratus femoris) steady the femoral head. Weak gluteus medius and minimus produce an unstable, tilting pelvis in gait.", "clin": [{"t": "Gluteus medius/minimus weakness", "d": "These muscles keep the pelvis level over the standing leg while the other leg swings; if they are weak or paralyzed the pelvis becomes unstable in walking and drops toward the unaffected (swing) side."}]},
 {"id": "3-26", "t": "Posterior Thigh Muscles", "d": "Three hamstrings (semitendinosus, semimembranosus, long head of biceps femoris) arise from the ischial tuberosity, extend the hip and flex the knee. The short head of biceps femoris does not cross the hip and is not counted as a hamstring. Because they span two joints, the book stresses warming them up before hard exercise.", "clin": [{"t": "Hamstring warm-up", "d": "Because the hamstrings cross both hip and knee, the book advises warming them up before vigorous exercise (stretching, getting blood flowing, activating the motor units)."}]},
 {"id": "3-27", "t": "Anterior Thigh Muscles", "d": "The anterior thigh compartment mainly extends the knee through the four-part quadriceps femoris, which ends in the quadriceps tendon and patellar ligament. Sartorius and rectus femoris cross both hip and knee, and the iliopsoas enters the upper thigh as the strongest hip flexor. Tensor fasciae latae acts through the iliotibial tract. The patellar reflex tests the femoral nerve.", "clin": [{"t": "Patellar reflex", "d": "Tapping the patellar ligament makes the bent knee kick into extension, which checks the quadriceps and its femoral nerve supply."}]},
 {"id": "3-28", "t": "Medial Thigh Muscles", "d": "The medial compartment adducts the thigh at the hip, with adductor magnus the strongest; gracilis also crosses the knee. Most are obturator-nerve muscles, with exceptions for pectineus (femoral) and the hamstring part of adductor magnus (tibial). Groin pulls usually involve adductor longus or magnus.", "clin": [{"t": "Groin pull", "d": "A groin pull is a strain or tear of one or more medial-compartment adductors, most often adductor longus or adductor magnus; it is a common sports injury."}]},
 {"id": "3-29", "t": "Anterior and Lateral Leg Muscles", "d": "The anterior leg compartment dorsiflexes the ankle, extends the toes and inverts the foot (deep fibular nerve), while the lateral compartment everts it (superficial fibular nerve). The book notes that lower limb flexor/extensor compartments are reversed relative to the upper limb because the limbs rotate differently in development. Anterior compartment syndrome is the clinical note.", "clin": [{"t": "Anterior compartment syndrome", "d": "Overuse of the anterior leg muscles ('anterior shin splints') causes pain that spreads to the ankle and top of the foot; swelling inside the tight compartment can squeeze nerves and vessels, and an acute, rapidly worsening case may need surgical release (fasciotomy)."}]},
 {"id": "3-30", "t": "Posterior Leg Muscles", "d": "The posterior leg compartment plantarflexes the ankle, flexes the toes and inverts the foot, all through the tibial nerve. A superficial group (gastrocnemius, soleus, plantaris) shares the calcaneal (Achilles) tendon; a deep group includes popliteus, the long toe flexors and tibialis posterior. Shin splints and Achilles tendinitis or rupture are the clinical notes.", "clin": [{"t": "Shin splints", "d": "Pain along the inner lower two-thirds of the tibia, common in athletes, mainly from repeated pulling of the tibialis posterior tendon at push-off when running."}, {"t": "Achilles tendinitis and rupture", "d": "The calcaneal tendon, the body's strongest, becomes inflamed with repeated stress such as running hills or uneven ground; rupture is serious because the poorly vascularized tendon heals slowly, as tendons generally do."}]},
 {"id": "3-31", "t": "Intrinsic Foot Muscles", "d": "The intrinsic sole muscles lie in four layers beneath the plantar aponeurosis and work alongside the long flexor tendons from the leg. They mirror the hand's pattern, including plantar interossei that adduct (PAD) and dorsal interossei that abduct (DAB) the toes. Plantar fasciitis is the clinical note.", "clin": [{"t": "Plantar fasciitis", "d": "Inflammation of the plantar aponeurosis where it attaches to the calcaneus is a frequent cause of heel pain, especially in joggers, with pain that can spread toward the toes."}]},
 {"id": "3-32", "t": "Summary of Lower Limb Muscles", "d": "A review plate grouping lower limb muscles by joint and action, from hip to intertarsal joints. Gluteal muscles extend, abduct and rotate the hip; anterior thigh extends the knee; medial thigh adducts; posterior thigh extends the hip and flexes the knee. In the leg, the lateral group everts, the anterior group dorsiflexes and the posterior group plantarflexes."}
];
